-- 90 VERIFY — [E20261012-DMF0082LATFIX] V1~V3 조회 전용 · V4 = 40·81·82 GET 1회씩 호출(GTT 만 사용, ROLLBACK) · V5 = 호출 뒤 MF_SP INSERT 계획 확인
-- * 기대: V1 마커 2(VD 1 + History 1) · V2 VALID/오류 0 · V3 VD 블록에 `AND    p_division_id = '82'` 가 뷰 WHERE 안 · V4 'OK' 3줄 · V5 VW_LAT=0 · MERGE_JOIN=0
-- * 10 실행 전에 돌면 V1=0 · V5 VW_LAT=1 — 그 자체가 적용 전 증거
-- * 사내 적용 뒤 실측(ZIOUI1 10-12): MF_SP INSERT 새 SQL_ID b9hn6zvmrhkhu PHV 4272580446 · VW_LAT 0 · 1회 CPU 1.15s→0.47s(40) / 1.7s→0.95~1.5s(k0101)
SET SERVEROUTPUT ON SIZE UNLIMITED
SET LINESIZE 300 PAGESIZE 500
SELECT 'V1 마커' CHK, COUNT(*) N, CASE WHEN COUNT(*) = 2 THEN 'PASS' ELSE '❌ FAIL (' || COUNT(*) || ')' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%E20261012-DMF0082LATFIX%';
SELECT 'V2 상태' CHK, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_ERRORS E WHERE E.NAME=O.OBJECT_NAME AND E.TYPE=O.OBJECT_TYPE) ERR_CNT,
       (SELECT COUNT(*) FROM USER_OBJECTS X WHERE X.STATUS<>'VALID' AND X.OBJECT_NAME IN (SELECT NAME FROM USER_DEPENDENCIES WHERE REFERENCED_NAME='PKG_DMF0082')) DEP_INVALID
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0082' ORDER BY O.OBJECT_TYPE;
SELECT 'V3 VD 블록' CHK, LINE, RTRIM(TEXT, CHR(10)||CHR(13)) TXT FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY'
   AND LINE BETWEEN (SELECT MIN(LINE)-3 FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261012-DMF0082LATFIX] 구 ON 절%')
                AND (SELECT MIN(LINE)+2 FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261012-DMF0082LATFIX] 구 ON 절%')
 ORDER BY LINE;
-- V4 — 40 · 81 · 82 GET 호출 (ADMIN / minyonglee1, 당월~+6개월, 전체 필터). 결과 커서는 행수만 세고 ROLLBACK
DECLARE
  rc1 SYS_REFCURSOR; rc2 SYS_REFCURSOR; rc3 SYS_REFCURSOR; rc4 SYS_REFCURSOR; rc5 SYS_REFCURSOR; rr SYS_REFCURSOR;
  v_from VARCHAR2(8) := TO_CHAR(TRUNC(SYSDATE,'MM'),'YYYYMMDD'); v_to VARCHAR2(8) := TO_CHAR(ADD_MONTHS(TRUNC(SYSDATE,'MM'),6)-1,'YYYYMMDD');
  t0 NUMBER; n PLS_INTEGER;
  FUNCTION cnt(rc IN OUT SYS_REFCURSOR) RETURN PLS_INTEGER IS k PLS_INTEGER := 0; cc INTEGER; BEGIN cc := DBMS_SQL.TO_CURSOR_NUMBER(rc); WHILE DBMS_SQL.FETCH_ROWS(cc) > 0 LOOP k := k + 1; END LOOP; DBMS_SQL.CLOSE_CURSOR(cc); RETURN k; END;
BEGIN
  FOR d IN (SELECT '40' dv FROM DUAL UNION ALL SELECT '81' FROM DUAL UNION ALL SELECT '82' FROM DUAL) LOOP
    t0 := DBMS_UTILITY.GET_TIME;
    SCM_MGR.PKG_DMF0082.P_DMF0082_GET_MAIN_DATA(d.dv, 'ALL', 'ALL', 'ALL', v_from, v_to, 'ALL', NULL, 'Current', 'N', 'minyonglee1', 'ADMIN', 'ALL', 'ALL', 'ALL', 'ALL', rc1, rc2, rc3, rc4, rc5, rr);
    n := cnt(rc1); CLOSE rc2; CLOSE rc3; CLOSE rc4; CLOSE rc5; CLOSE rr;
    DBMS_OUTPUT.PUT_LINE('V4 div ' || d.dv || ' OK  SP ' || TO_CHAR((DBMS_UTILITY.GET_TIME - t0)/100, 'FM99990.00') || 's  RC1 rows=' || n);
    ROLLBACK;
  END LOOP;
END;
/
-- V5 — 호출 뒤 MF_SP INSERT 자식 커서 계획: VW_LAT 0 · MERGE JOIN 0 이면 lateral 제거 확인
SELECT 'V5 MF_SP 계획' CHK, S.INST_ID, S.SQL_ID, S.CHILD_NUMBER CH, S.PLAN_HASH_VALUE PHV, S.EXECUTIONS EX, ROUND(S.ELAPSED_TIME/1e6/GREATEST(S.EXECUTIONS,1),1) SEC_PER_EX,
       ROUND(S.CPU_TIME/1e6/GREATEST(S.EXECUTIONS,1),1) CPU_PER_EX, ROUND(S.ROWS_PROCESSED/GREATEST(S.EXECUTIONS,1)) ROWS_PER_EX, S.LAST_LOAD_TIME LOADED,
       (SELECT COUNT(*) FROM GV$SQL_PLAN P WHERE P.INST_ID=S.INST_ID AND P.SQL_ID=S.SQL_ID AND P.CHILD_NUMBER=S.CHILD_NUMBER AND P.OBJECT_NAME LIKE 'VW_LAT%') VW_LAT,
       (SELECT COUNT(*) FROM GV$SQL_PLAN P WHERE P.INST_ID=S.INST_ID AND P.SQL_ID=S.SQL_ID AND P.CHILD_NUMBER=S.CHILD_NUMBER AND P.OPERATION='MERGE JOIN') MERGE_JOIN,
       (SELECT LISTAGG(P.OPERATION||' '||NVL(P.OPTIONS,''), ' > ') WITHIN GROUP (ORDER BY P.ID) FROM GV$SQL_PLAN P
         WHERE P.INST_ID=S.INST_ID AND P.SQL_ID=S.SQL_ID AND P.CHILD_NUMBER=S.CHILD_NUMBER AND P.ID BETWEEN 6 AND 9) OPS_6_9,
       CASE WHEN (SELECT COUNT(*) FROM GV$SQL_PLAN P WHERE P.INST_ID=S.INST_ID AND P.SQL_ID=S.SQL_ID AND P.CHILD_NUMBER=S.CHILD_NUMBER AND P.OBJECT_NAME LIKE 'VW_LAT%') = 0 THEN 'PASS — lateral 없음' ELSE '❌ VW_LAT 잔존 (적용 전 커서면 LOADED 시각 확인)' END JUDGE
  FROM GV$SQL S WHERE UPPER(S.SQL_TEXT) LIKE 'INSERT%INTO SCM_MGR.GT_DMF0082_MF_SP (%'
   AND DBMS_LOB.INSTR(S.SQL_FULLTEXT, 'DIVISION_ID = ''82'' AND :B') > 0   -- 패치된 문장 = 뷰 WHERE 안에 바인드 조건 (PL/SQL 은 주석을 떼고 보내므로 마커로는 못 찾음)
 ORDER BY S.LAST_ACTIVE_TIME DESC FETCH FIRST 5 ROWS ONLY;
PROMPT --  0 rows = V4 뒤에도 패치 문장 커서가 없음 → 10 미적용 또는 V4 실행 안 됨. 사내 실측: SQL_ID b9hn6zvmrhkhu PHV 4272580446 VW_LAT 0 MERGE_JOIN 0
